./hts_internal.h:130:static inline int find_file_extension(const char *fn, char ext_out[static HTS_MAX_EXT_LEN])
   120   *
   121   * This is needed when multi-threading and writing indices on the fly.
   122   * At the point of writing a record we know the virtual offset for start
   123   * and end, but that end virtual offset may be the end of the current
   124   * block.  In standard indexing our end virtual offset becomes the start
   125   * of the next block.  Thus to ensure bit for bit compatibility we
   126   * detect this boundary case and fix it up here.
   127   */
   128  void bgzf_idx_amend_last(BGZF *fp, hts_idx_t *hidx, uint64_t offset);
   129
   130  static inline int find_file_extension(const char *fn, char ext_out[static HTS_MAX_EXT_LEN])
   131  {
   132      const char *delim = fn ? strstr(fn, HTS_IDX_DELIM) : NULL, *ext;
   133      if (!fn) return -1;
   134      if (!delim) delim = fn + strlen(fn);
   135      for (ext = delim; ext > fn && *ext != '.' && *ext != '/'; --ext) {}
   136      if (*ext == '.' &&
   137          ((delim - ext == 3 && ext[1] == 'g' && ext[2] == 'z') || // permit .sam.gz as a valid file extension
   138          (delim - ext == 4 && ext[1] == 'b' && ext[2] == 'g' && ext[3] == 'z'))) // permit .vcf.bgz as a valid file extension
   139      {
   140          for (ext--; ext > fn && *ext != '.' && *ext != '/'; --ext) {}
   141      }
   142      if (*ext != '.' || delim - ext > HTS_MAX_EXT_LEN || delim - ext < 4) return -1;
   143      memcpy(ext_out, ext + 1, delim - ext - 1);
   144      ext_out[delim - ext - 1] = '\0';
   145      return 0;
   146  }
